def canonizar_ruts_existentes(apps, schema_editor):
    """
    Deja los RUT ya guardados en la forma canónica (con puntos y guion).
    - Si el RUT no tiene forma de RUT, se deja tal cual (no se inventan datos).
    - Si al canonizarlo chocaría con otra ficha que ya tiene ese RUT, se deja
      tal cual para no violar el "unique" ni pisar datos; hay que revisarlo a mano.
    """
    Proveedor = apps.get_model('entidades', 'Proveedor')
    for proveedor in Proveedor.objects.all():
        if not RUT_REGEX.match(normalizar_rut(proveedor.rut)):
            continue
        canonico = rut_canonico(proveedor.rut)
        if canonico == proveedor.rut:
            continue
        if Proveedor.objects.filter(rut=canonico).exclude(pk=proveedor.pk).exists():
            continue
        Proveedor.objects.filter(pk=proveedor.pk).update(rut=canonico)


